/**
 * E2E（端到端加密）本会话状态 —— 仅进程内内存，不持久化。
 * 口令只用于派生 KEK（PBKDF2），派生出的 KEK 不可导出；口令与密钥均不入 localStorage/IndexedDB。
 */
import { Injectable, signal } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class E2eSessionService {
  private passphrase = signal<string | null>(null);
  /** 授权（团队 KEK）口令：被授权人访问他人授予的 E2E 文件时用来解开授权信封。亦仅进程内内存。 */
  private grantPassphrase = signal<string | null>(null);

  /** 开启 E2E 并记录加密口令（替换旧口令）。 */
  enableE2E(p: string): void {
    this.passphrase.set(p);
  }

  /** 关闭 E2E，丢弃口令。 */
  disableE2E(): void {
    this.passphrase.set(null);
  }

  /** 是否已开启 E2E（已有口令）。 */
  isE2EEnabled(): boolean {
    return this.passphrase() !== null && this.passphrase()!.length > 0;
  }

  /** 取当前加密口令（未开启时返回 null）。 */
  getE2EPassphrase(): string | null {
    return this.passphrase();
  }

  /** 记录授权（团队 KEK）口令，供后续访问其他被授权文件的 E2E 内容复用。 */
  setGrantPassphrase(p: string): void {
    this.grantPassphrase.set(p);
  }

  /** 取当前授权（团队 KEK）口令；未设置则返回 null。 */
  getGrantPassphrase(): string | null {
    return this.grantPassphrase();
  }
}
