import { TestBed } from '@angular/core/testing';

import { E2eSessionService } from './e2e-session.service';

describe('E2eSessionService（口令会话，不进 localStorage）', () => {
  let svc: E2eSessionService;

  beforeEach(() => {
    TestBed.configureTestingModule({});
    svc = TestBed.inject(E2eSessionService);
  });

  it('初始未启用 E2E', () => {
    expect(svc.isE2EEnabled()).toBeFalse();
    expect(svc.getE2EPassphrase()).toBeNull();
  });

  it('enableE2E 后口令可取且 isE2EEnabled 为 true', () => {
    svc.enableE2E('my-passphrase');
    expect(svc.isE2EEnabled()).toBeTrue();
    expect(svc.getE2EPassphrase()).toBe('my-passphrase');
  });

  it('disableE2E 后口令清空', () => {
    svc.enableE2E('p');
    svc.disableE2E();
    expect(svc.isE2EEnabled()).toBeFalse();
    expect(svc.getE2EPassphrase()).toBeNull();
  });

  it('空口令不算启用', () => {
    svc.enableE2E('');
    expect(svc.isE2EEnabled()).toBeFalse();
  });

  it('分享授权口令（grant）独立存取', () => {
    expect(svc.getGrantPassphrase()).toBeNull();
    svc.setGrantPassphrase('grant-pass');
    expect(svc.getGrantPassphrase()).toBe('grant-pass');
    // grant 与本地口令互不影响
    svc.enableE2E('local-pass');
    expect(svc.getGrantPassphrase()).toBe('grant-pass');
    expect(svc.getE2EPassphrase()).toBe('local-pass');
  });
});
